    sol: "$cutoff = (Get-Date).AddDays(-90); Get-ADUser -Filter * -Properties LastLogonTimestamp | Where-Object { $_.LastLogonTimestamp -and [DateTime]::FromFileTime($_.LastLogonTimestamp) -lt $cutoff } | Select-Object Name, SamAccountName, @{N='LastLogon';E={[DateTime]::FromFileTime($_.LastLogonTimestamp)}}",
    exp: "LastLogonTimestamp is replicated across DCs, unlike LastLogon which is per-DC and gives inaccurate results unless checked on every DC — it's the correct attribute for a fleet-wide stale-account report, and needs the FileTime conversion since AD stores it as a large integer.",
