    q: "Write a PowerShell script using try/catch/finally that connects to a remote server, runs a command, and ensures the session is always closed even if the command fails.",
    sol: "$session = New-PSSession -ComputerName 'srv01'\ntry {\n  Invoke-Command -Session $session -ScriptBlock { Get-Service -Name 'nonexistent-service' -ErrorAction Stop }\n} catch {\n  Write-Warning \"Command failed: $($_.Exception.Message)\"\n} finally {\n  Remove-PSSession $session\n}",
