    sol: "$serviceAccountOU = 'OU=ServiceAccounts,DC=corp,DC=example,DC=com'\n$flagged = Get-ADUser -Filter 'PasswordNeverExpires -eq $true' -Properties PasswordNeverExpires, DistinguishedName |\n  Where-Object { $_.DistinguishedName -notlike \"*$serviceAccountOU\" }\n$flagged | Select-Object Name, SamAccountName, DistinguishedName |\n  Export-Csv -Path .\\password-never-expires-audit.csv -NoTypeInformation\nWrite-Output \"$($flagged.Count) non-service accounts found with PasswordNeverExpires enabled.\"",
